// fizzBuzzSchema.ts
// What FizzBuzz says for each number from 1 to 100, in order.
export interface FizzBuzzResponse {
    lines: (number | "Fizz" | "Buzz" | "FizzBuzz")[];
}

// main.ts
import fs from "fs";
import path from "path";
import { createJsonTranslator, createLanguageModel } from "typechat";
import { createTypeScriptJsonValidator } from "typechat/ts";
import { FizzBuzzResponse } from "./fizzBuzzSchema";

const model = createLanguageModel(process.env);
const schema = fs.readFileSync(path.join(__dirname, "fizzBuzzSchema.ts"), "utf8");
const validator = createTypeScriptJsonValidator<FizzBuzzResponse>(schema, "FizzBuzzResponse");
const translator = createJsonTranslator(model, validator);

async function main() {
    const response = await translator.translate("Play FizzBuzz for the numbers 1 to 100.");
    if (!response.success) {
        console.log(response.message);
        return;
    }
    console.log(response.data.lines.join("\n"));
}

main();

