from typesafe_sdk import Choice, TypeSafeClient

with TypeSafeClient(model="jev-latest") as client:  # reads TYPESAFE_API_KEY
    for n in range(1, 101):
        response = client.system_one(
            state=str(n),
            questions={
                "word": Choice(
                    instructions="Which word does this number get in FizzBuzz",
                    criteria={
                        "Fizz": "A multiple of 3 but not of 5",
                        "Buzz": "A multiple of 5 but not of 3",
                        "FizzBuzz": "A multiple of both 3 and 5",
                        "number": "A multiple of neither",
                    },
                ),
            },
        )
        word = response.choices["word"].choice
        print(n if word == "number" else word)
